import { test, expect } from '@playwright/test';
import { injectAxe, checkA11y } from 'axe-playwright';

test.describe('WCAG 2.1 AA Color Contrast Compliance', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    await injectAxe(page);
  });

  test('should have sufficient color contrast on primary buttons', async ({ page }) => {
    const primaryButton = page.getByRole('button', { name: /submit/i });

    const computedStyle = await primaryButton.evaluate((element) => {
      const style = window.getComputedStyle(element);
      return {
        color: style.color,
        backgroundColor: style.backgroundColor,
      };
    });

    const contrastRatio = calculateContrastRatio(
      computedStyle.color,
      computedStyle.backgroundColor
    );

    expect(contrastRatio).toBeGreaterThanOrEqual(4.5);
  });

  test('should have sufficient color contrast on text and background', async ({ page }) => {
    const mainContent = page.getByRole('main');

    const textElements = await mainContent.locator('p, span, a, h1, h2, h3, h4, h5, h6').all();

    for (const element of textElements) {
      const computedStyle = await element.evaluate((el) => {
        const style = window.getComputedStyle(el);
        return {
          color: style.color,
          backgroundColor: style.backgroundColor,
          fontSize: style.fontSize,
        };
      });

      const contrastRatio = calculateContrastRatio(
        computedStyle.color,
        computedStyle.backgroundColor
      );

      const fontSize = parseFloat(computedStyle.fontSize);
      const minContrast = fontSize >= 18 ? 3 : 4.5;

      expect(contrastRatio).toBeGreaterThanOrEqual(minContrast);
    }
  });

  test('should pass axe accessibility checks for color contrast', async ({ page }) => {
    await checkA11y(page, null, {
      rules: {
        'color-contrast': { enabled: true },
      },
    });
  });

  test('should have sufficient contrast on form labels and inputs', async ({ page }) => {
    const form = page.getByRole('form');
    const labels = form.getByRole('label');

    const labelCount = await labels.count();

    for (let i = 0; i < labelCount; i++) {
      const label = labels.nth(i);
      const computedStyle = await label.evaluate((element) => {
        const style = window.getComputedStyle(element);
        return {
          color: style.color,
          backgroundColor: style.backgroundColor,
        };
      });

      const contrastRatio = calculateContrastRatio(
        computedStyle.color,
        computedStyle.backgroundColor
      );

      expect(contrastRatio).toBeGreaterThanOrEqual(4.5);
    }
  });

  test('should have sufficient contrast on interactive elements', async ({ page }) => {
    const links = page.getByRole('link');
    const linkCount = await links.count();

    for (let i = 0; i < linkCount; i++) {
      const link = links.nth(i);
      const computedStyle = await link.evaluate((element) => {
        const style = window.getComputedStyle(element);
        return {
          color: style.color,
          backgroundColor: style.backgroundColor,
        };
      });

      const contrastRatio = calculateContrastRatio(
        computedStyle.color,
        computedStyle.backgroundColor
      );

      expect(contrastRatio).toBeGreaterThanOrEqual(4.5);
    }
  });

  test('should maintain contrast on focus states', async ({ page }) => {
    const button = page.getByRole('button').first();

    await button.focus();

    const focusedStyle = await button.evaluate((element) => {
      const style = window.getComputedStyle(element);
      return {
        color: style.color,
        backgroundColor: style.backgroundColor,
        outline: style.outline,
      };
    });

    const contrastRatio = calculateContrastRatio(
      focusedStyle.color,
      focusedStyle.backgroundColor
    );

    expect(contrastRatio).toBeGreaterThanOrEqual(4.5);
    expect(focusedStyle.outline).not.toBe('none');
  });
});

function rgbToLuminance(r: number, g: number, b: number): number {
  const [rs, gs, bs] = [r, g, b].map((val) => {
    val = val / 255;
    return val <= 0.03928 ? val / 12.92 : Math.pow((val + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;
}

function parseColor(colorString: string): { r: number; g: number; b: number } {
  const rgbMatch = colorString.match(/rgb\((\d+),\s*(\d+),\s*(\d+)\)/);
  if (rgbMatch) {
    return {
      r: parseInt(rgbMatch[1], 10),
      g: parseInt(rgbMatch[2], 10),
      b: parseInt(rgbMatch[3], 10),
    };
  }

  const rgbaMatch = colorString.match(/rgba\((\d+),\s*(\d+),\s*(\d+),\s*([\d.]+)\)/);
  if (rgbaMatch) {
    const alpha = parseFloat(rgbaMatch[4]);
    return {
      r: Math.round(parseInt(rgbaMatch[1], 10) * alpha + 255 * (1 - alpha)),
      g: Math.round(parseInt(rgbaMatch[2], 10) * alpha + 255 * (1 - alpha)),
      b: Math.round(parseInt(rgbaMatch[3], 10) * alpha + 255 * (1 - alpha)),
    };
  }

  return { r: 0, g: 0, b: 0 };
}

function calculateContrastRatio(foreground: string, background: string): number {
  const fgColor = parseColor(foreground);
  const bgColor = parseColor(background);

  const fgLuminance = rgbToLuminance(fgColor.r, fgColor.g, fgColor.b);
  const bgLuminance = rgbToLuminance(bgColor.r, bgColor.g, bgColor.b);

  const lighter = Math.max(fgLuminance, bgLuminance);
  const darker = Math.min(fgLuminance, bgLuminance);

  return (lighter + 0.05) / (darker + 0.05);
}
